local ResourceModule = CS.Engine.Modules.ResourceModule
---@type Pool
local Pool = import("Game.Utils.Pool")


--- lua:
local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")

---@class ParkourParticleMgr
local ParkourParticleMgr = Class("ParkourParticleMgr")


-- =================================================================


function ParkourParticleMgr:__init(rootTransform)
    self.pools = {}
    self.loaders = {}
    self.cos = {}
    self.runParticles = {}
    self.coIndex = 0
    self.root = rootTransform
end

function ParkourParticleMgr:__delete()
    for k,v in pairs(self.pools) do
        v:Clear()
    end
    for k,v in pairs(self.loaders) do
        v:Release()
    end
    for k,v in pairs(self.cos) do
        --CoStop(v)
        CoStop(v)
    end
end

---@param callback function  func(particle)
function ParkourParticleMgr:PlayParticle(path, parent, duration, pos, scale, callback)
    if isNull(self.root) then
        printError("ParkourParticleMgr:poll root is null")
        return
    end
    local pool = self.pools[path]
    self.coIndex = self.coIndex + 1
    local index = self.coIndex
    if pool == nil then
        ResourceModule.LoadBundleAsync(path, function (loader, ok, resultObject)
            if ok then
                self.loaders[path] = loader
                pool = Pool.New(function()
                    local go = ResourceModule.Instantiate(resultObject)
                    go:SetActive(false)
                    go.transform:SetParent(self.root)
                    return go
                end,1)
                self.pools[path] = pool

                self:DoPlayParticle(pool, parent, pos, scale, duration,callback,index)
            end
        end)
    else
        self:DoPlayParticle(pool, parent, pos, scale, duration,callback,index)
    end
    return index
end

---@param pool Pool
function ParkourParticleMgr:DoPlayParticle(pool, parent, pos, scale, duration,callback,index)
    local go = pool:Obtain()
    if parent then
        go.transform:SetParent(parent.transform)    
    else
        go.transform:SetParent(self.root)
    end
    go.transform.localPosition = pos
    go.transform.localScale = scale
    go:SetActive(true)
    if callback then
        callback(go)
    end

    CoStop(self.cos[index])
    self.cos[index] = CoStart(function()
    --self.cos[index] = CoStart(function()
        --CoYield(duration)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( duration ))
        go:SetActive(false)
        go.transform:SetParent(self.root)
        pool:Free(go)
        self.cos[index] = nil
        self.runParticles[index] = nil
    end)
    self.runParticles[index] = {go = go, coIndex = index,pool = pool}
end

function ParkourParticleMgr:StopParticle(coIndex)
    if self.runParticles[coIndex] then
        --CoStop(self.cos[coIndex])
        CoStop(self.cos[coIndex])
        self.runParticles[coIndex].go:SetActive(false)
        self.runParticles[coIndex].go.transform:SetParent(self.root)
        self.runParticles[coIndex].pool:Free(self.runParticles[coIndex].go)
        self.runParticles[coIndex] = nil
        self.cos[coIndex] = nil
    end
end

return ParkourParticleMgr